def ds(n):
    if n < 10:
        return n
    return n % 10 + ds(n // 10)

def rev(n, acc=0):
    if n == 0:
        return acc
    return rev(n // 10, acc * 10 + n % 10)

print(ds(9875), rev(9875), rev(1200))

